{"chunk_id":"516070","wall_time_seconds":0.000007974,"exit_code":0,"original_token_count":4539,"output":"#!/usr/bin/env python3
"""Audit observer-arrival versus comet-emission UTC for a selected completed case.

No model, ephemeris, GTI, empirical-validation or plot inputs are changed. The
default output replaces the historical light_travel_time_audit.json only when
this script is explicitly run without --check-selection or --self-test.
"""
from __future__ import annotations
import argparse
import csv
import datetime as dt
import hashlib
import json
from pathlib import Path

import numpy as np
from astropy.time import Time
from case_selection import case_provenance, select_case

HERE=Path(__file__).resolve().parent
ROOT=HERE.parent
AU_KM=149597870.7
C_KM_S=299792.458
DAY_S=86400.
FIELDS=('n_cm3','speed_kms','flux_cm2_s','incident_flux_cm2_s')
UNITS={'n_cm3':'cm^-3','speed_kms':'km s^-1','flux_cm2_s':'cm^-2 s^-1','incident_flux_cm2_s':'cm^-2 s^-1'}
ORBIT_SOURCE='https://xmm-tools.cosmos.esa.int/external/xmm_user_support/documentation/uhb/orbit.html'

def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()

def table(path,delimiter='\t'):
    return np.genfromtxt(path,names=True,delimiter=delimiter,dtype=None,encoding='utf8')

def checked_interpolate(query,times,values,label):
    query=np.asarray(query,dtype=float)
    if np.any(~np.isfinite(query)) or query.min()<times[0]-1e-11 or query.max()>times[-1]+1e-11:
        raise ValueError(f'{label}: requested epochs are outside source coverage; no extrapolation permitted')
    if values.ndim==1:return np.interp(query,times,values)
    return np.stack([np.interp(query,times,values[:,j]) for j in range(values.shape[1])],axis=-1)

def emission_time(arrival,comet_position,earth_position):
    """Solve te=to-|rC(te)-rEarth(to)|/c in common geometric coordinates."""
    arrival=np.asarray(arrival,dtype=float);observer=earth_position(arrival);emission=arrival.copy()
    for _ in range(12):
        delay=np.linalg.norm(comet_position(emission)-observer,axis=-1)*AU_KM/C_KM_S/DAY_S
        updated=arrival-delay
        if np.max(abs(updated-emission))<1e-12:return updated
        emission=updated
    raise ValueError('Comet-emission light-time iteration did not converge')

def arrival_time(emission,comet_position,earth_position):
    """Invert the retarded mapping to include every shifted native probe knot."""
    emission=np.asarray(emission,dtype=float);source=comet_position(emission);arrival=emission.copy()
    for _ in range(12):
        updated=emission+np.linalg.norm(source-earth_position(arrival),axis=-1)*AU_KM/C_KM_S/DAY_S
        if np.max(abs(updated-arrival))<1e-12:return updated
        arrival=updated
    raise ValueError('Observer-arrival light-time iteration did not converge')

class Inputs:
    def __init__(self,case):
        self.metadata=json.loads((ROOT/'inputs/metadata.json').read_text())
        self.origin=float(self.metadata['origin_mjd_utc'])
        self.matrix=np.asarray(json.loads((HERE/'coordinate_system.json').read_text())['ecliptic_to_solar_equatorial_matrix'])
        self.comet=table(HERE/'ephemeris_comet.tsv');self.earth=table(HERE/'ephemeris_wind.tsv')
        self.comet_time=self.comet['mjd_utc']-self.origin;self.earth_time=self.earth['mjd_utc']-self.origin
        self.comet_xyz=np.column_stack([self.comet[k] for k in ['x_au','y_au','z_au']])
        self.earth_xyz=np.column_stack([self.earth[k] for k in ['x_au','y_au','z_au']])
        self.comet_vxyz=np.column_stack([self.comet[k] for k in ['vx_au_day','vy_au_day','vz_au_day']])*AU_KM/DAY_S
        a=table(ROOT/f'results/{case}/probe.csv',',');a=a[a['probe_id']==0]
        time_name='day' if 'day' in a.dtype.names else 'tday'
        order=np.argsort(a[time_name]);a=a[order];self.probe_time=np.asarray(a[time_name],dtype=float)
        if len(a)<2 or np.any(np.diff(self.probe_time)<=0):raise ValueError('Need unique ordered comet probe samples')
        self.n=np.asarray(a['n_cm3'],dtype=float)
        self.wind_local=np.column_stack([a[k] for k in ['vr_kms','vtheta_kms','vphi_kms']])
        if np.any(~np.isfinite(self.wind_local)) or np.any(~np.isfinite(self.n)) or np.any(self.n<=0):raise ValueError('Invalid comet probe state')
        derived_speed=np.linalg.norm(self.wind_local,axis=1)
        self.native_consistency={'maximum_relative_speed_column_error':float(np.max(abs(derived_speed/a['speed_kms']-1))),'maximum_relative_flux_column_error':float(np.max(abs(self.n*derived_speed*1e5/a['flux_cm2_s']-1)))}

    def comet_position(self,t):return checked_interpolate(t,self.comet_time,self.comet_xyz,'Comet geometric ephemeris')
    def earth_position(self,t):return checked_interpolate(t,self.earth_time,self.earth_xyz,'Earth geometric ephemeris')
    def emission(self,t):return emission_time(t,self.comet_position,self.earth_position)
    def arrival(self,t):return arrival_time(t,self.comet_position,self.earth_position)
    def utc(self,t):return Time(np.asarray(t)+self.origin,format='mjd',scale='utc').isot

    def evaluate(self,t):
        """All density/velocity/ephemeris quantities refer to the same comet UTC."""
        t=np.asarray(t,dtype=float)
        n=checked_interpolate(t,self.probe_time,self.n,'Comet MHD probe')
        local=checked_interpolate(t,self.probe_time,self.wind_local,'Comet MHD velocity')
        pos=self.comet_position(t)@self.matrix.T
        vc=checked_interpolate(t,self.comet_time,self.comet_vxyz,'Comet velocity ephemeris')@self.matrix.T
        radius=np.linalg.norm(pos,axis=-1);longitude=np.arctan2(pos[...,1],pos[...,0]);theta=np.arccos(pos[...,2]/radius)
        er=pos/radius[...,None]
        et=np.stack([np.cos(theta)*np.cos(longitude),np.cos(theta)*np.sin(longitude),-np.sin(theta)],axis=-1)
        ep=np.stack([-np.sin(longitude),np.cos(longitude),np.zeros_like(longitude)],axis=-1)
        wind=local[...,0,None]*er+local[...,1,None]*et+local[...,2,None]*ep
        speed=np.linalg.norm(wind,axis=-1)
        return np.stack([n,speed,n*speed*1e5,n*np.linalg.norm(wind-vc,axis=-1)*1e5],axis=-1)

def breakpoint_grid(start,stop,knots,maximum_step_seconds=None):
    points=[start,stop,*np.asarray(knots)[(knots>start)&(knots<stop)]]
    if maximum_step_seconds:
        points.extend(np.linspace(start,stop,int(np.ceil((stop-start)*DAY_S/maximum_step_seconds))+1))
    return np.unique(points)

def integrate(spans,knots,evaluate,retard,quadrature_order=8):
    abscissa,weight=np.polynomial.legendre.leggauss(quadrature_order)
    unshifted=np.zeros(4);retarded=np.zeros(4);duration=0.
    for start,stop in spans:
        grid=breakpoint_grid(start,stop,knots)
        midpoint=(grid[1:]+grid[:-1])/2;halfwidth=(grid[1:]-grid[:-1])/2
        query=midpoint[:,None]+halfwidth[:,None]*abscissa
        weights=halfwidth[:,None]*weight
        unshifted+=np.sum(evaluate(query.ravel()).reshape(*query.shape,4)*weights[...,None],axis=(0,1))
        retarded+=np.sum(evaluate(retard(query.ravel())).reshape(*query.shape,4)*weights[...,None],axis=(0,1))
        duration+=stop-start
    return unshifted/duration,retarded/duration,duration*DAY_S

def comparison(a,b):
    return {field:{'simultaneous_UTC_mean':float(a[i]),'photon_emission_time_mean':float(b[i]),'relative_change':float(b[i]/a[i]-1)} for i,field in enumerate(FIELDS)}

def self_test():
    distance=1.881;delay=distance*AU_KM/C_KM_S/DAY_S
    earth=lambda t:np.zeros((*np.asarray(t).shape,3))
    comet=lambda t:np.broadcast_to([distance,0.,0.],(*np.asarray(t).shape,3))
    times=np.linspace(31,34,31);emission=emission_time(times,comet,earth)
    assert np.max(abs(emission-(times-delay)))<1e-12
    assert np.max(abs(arrival_time(emission,comet,earth)-times))<1e-12
    model=lambda t:np.stack([2+np.asarray(t),3+2*np.asarray(t),4+3*np.asarray(t),5+4*np.asarray(t)],axis=-1)
    spans=[(32.1,32.2),(32.4,32.55)]
    a,b,seconds=integrate(spans,np.arange(30,35,.01),model,lambda t:t-delay)
    assert np.max(abs((b-a)+delay*np.arange(1,5)))<1e-12
    assert abs(seconds-.25*DAY_S)<1e-6
    try:checked_interpolate([1.1],np.array([0.,1.]),np.array([1.,2.]),'synthetic')
    except ValueError:pass
    else:raise AssertionError('Extrapolation was accepted')
    print(json.dumps({'synthetic_retarded_and_inverse_mapping':'passed','disjoint_GTI_integration_and_sign':'passed','no_extrapolation':'passed','empirical_products_modified':False},indent=2))

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--case',help='Completed results/NAME; default reference_selection.json, else historical completed priority')
    parser.add_argument('--check-selection',action='store_true',help='Print case/input provenance, then exit without analysis or output changes')
    parser.add_argument('--self-test',action='store_true',help='Run synthetic numerical checks only; no empirical products changed')
    parser.add_argument('--output-file',type=Path,default=HERE/'light_travel_time_audit.json')
    parser.add_argument('--dense-step-seconds',type=float,default=1.,help='Maximum spacing for sampled full-pointing extrema, plus every native/retarded knot (default1s)')
    parser.add_argument('--no-series',action='store_true',help='Omit the compact60s arrival/emission comparison TSV')
    args=parser.parse_args()
    if args.self_test:self_test();return
    if not(.1<=args.dense_step_seconds<=30):parser.error('--dense-step-seconds must be between0.1 and30')
    try:case,selection=select_case(ROOT,explicit=args.case)
    except (ValueError,OSError,json.JSONDecodeError) as error:parser.error(str(error))
    paths=[ROOT/'inputs/metadata.json',HERE/'coordinate_system.json',HERE/'ephemeris_comet.tsv',HERE/'ephemeris_wind.tsv',HERE/'xmm_gtis.tsv',HERE/'inputs_summary.json',Path(__file__).resolve()]
    provenance={'case':case_provenance(ROOT,case),'inputs':{str(p.relative_to(ROOT)):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in paths}}
    if args.check_selection:
        print(json.dumps({'reference_case':case,'reference_selection':selection,'provenance':provenance,'output_would_be':str(args.output_file),'empirical_products_modified':False},indent=2));return
    data=Inputs(case)
    window=json.loads((HERE/'inputs_summary.json').read_text())['windows']['manuscript_all_pointings']
    start,stop=np.asarray([window['start_mjd_utc'],window['stop_mjd_utc']])-data.origin
    # Include knots whose retarded-arrival images fall inside the pointing window.
    nearby=data.probe_time[(data.probe_time>=start-.03)&(data.probe_time<=stop+.01)]
    ephem_near=data.comet_time[(data.comet_time>=start-.03)&(data.comet_time<=stop+.01)]
    knots=np.unique(np.r_[nearby,data.arrival(nearby),ephem_near,data.arrival(ephem_near)])
    grid=breakpoint_grid(start,stop,knots,args.dense_step_seconds)
    emission=data.emission(grid);unshifted=data.evaluate(grid);retarded=data.evaluate(emission)
    change=retarded/unshifted-1;delay=(grid-emission)*DAY_S
    maximum={}
    for i,field in enumerate(FIELDS):
        k=int(np.argmax(abs(change[:,i])))
        maximum[field]={'maximum_absolute_fractional_change':float(abs(change[k,i])),'signed_fractional_change_at_maximum':float(change[k,i]),'observer_arrival_utc':str(data.utc(grid[k])),'comet_emission_utc':str(data.utc(emission[k])),'simultaneous_value':float(unshifted[k,i]),'emission_time_value':float(retarded[k,i])}
    gtis=table(HERE/'xmm_gtis.tsv');detectors={};frame_means={}
    for detector in ['pn','mos1','mos2']:
        selected=gtis[gtis['detector']==detector]
        spans=list(zip(selected['start_mjd_utc']-data.origin,selected['stop_mjd_utc']-data.origin))
        a,b,exposure=integrate(spans,knots,data.evaluate,data.emission)
        low_a,low_b,_=integrate(spans,knots,data.evaluate,data.emission,4)
        detectors[detector]={'intervals':len(spans),'exposure_seconds':float(exposure),'mean_shift_comparison':comparison(a,b),'quadrature_4_vs_8_maximum_relative_difference':float(max(np.max(abs(low_a/a-1)),np.max(abs(low_b/b-1))))}
        for frame in np.unique(selected['frame']):
