    report={'created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'case':case,'reference_case':case,'reference_selection':selection,'provenance':provenance,'units':UNITS,'physical_time_convention':{'observer_time':'XMM GTIs and full published pointing limits are photon-arrival UTC at the observer.','comet_time':'Both MHD state and comet velocity/position are evaluated at the same emission UTC.','equation':'t_em=t_obs-|r_comet(t_em)-r_Earth(t_obs)|/c','observer_proxy':'Geometric Earth-center Horizons state (ephemeris_wind.tsv is deliberately target399, not Wind spacecraft). XMM orbital light-path difference is conservatively <=1s; the actual XMM orbital correction is not computed.','observer_proxy_primary_source':ORBIT_SOURCE,'observer_proxy_source_context':'ESA handbook quotes initial apogee about115000km and May2025 apogee height93300km; adding Earth radius still gives substantially less than one light-second.','other_approximations':'Sun-centered geometric ecliptic-J2000 vectors at different epochs; ignores the much smaller Sun barycentric displacement during~939s, relativistic light propagation and subsecond spacecraft-clock/barycentric effects.'},'evaluation':'Linear interpolation of native comet-probe density and local(r,theta,phi) velocity; rotate using same-epoch geometric comet basis, derive bulk speed/n|v|, and subtract same-epoch comet Cartesian velocity for incident flux. No extrapolation.','native_column_consistency':data.native_consistency,'probe_cadence_seconds':{'minimum':float(np.diff(data.probe_time).min()*DAY_S),'median':float(np.median(np.diff(data.probe_time))*DAY_S),'maximum':float(np.diff(data.probe_time).max()*DAY_S)},'light_travel_seconds':float(np.median(delay)),'light_travel_seconds_min_median_max':np.percentile(delay,[0,50,100]).tolist(),'retarded_geometric_distance_au_min_median_max':(np.percentile(delay,[0,50,100])*C_KM_S/AU_KM).tolist(),'full_pointing':{'observer_start_utc':window['start_utc'],'observer_stop_utc':window['stop_utc'],'emission_start_utc':str(data.utc(emission[0])),'emission_stop_utc':str(data.utc(emission[-1])),'sampled_times':len(grid),'maximum_grid_spacing_seconds':float(np.diff(grid).max()*DAY_S),'maximum_changes':maximum},'detector_GTI_means':detectors,'frame_GTI_means':frame_means,'mean_shift_comparison':detectors['pn']['mean_shift_comparison'],'decision':{'one_percent_comparison_threshold':.01,'full_pointing_any_field_exceeds_one_percent':exceeds,'PN_weighted_any_field_exceeds_one_percent':pn_exceeds,'recommendation':'Explicit observer-arrival/emission alignment warrants attention for the selected case.' if exceeds or pn_exceeds else 'Sampled shifts are below1% for the selected case; keep the~939s convention disclosed. This does not bound unresolved subcadence structure.'},'limitations':['GTI boundaries are retained exactly; Gauss quadrature is split at native and retarded probe/ephemeris knots.','Reported full-pointing maxima are sampled at<=1s by default plus knots; not rigorous continuum bounds or constraints on structures unresolved by the native probe cadence.','This is a case-specific timing audit; the historical wide_medium0.13% exposure-mean result cannot bound sharper final solutions.','The correction converts a comet-time wind prediction to observer-arrival labeling. It is not solar-wind transport from Earth to the comet.']}
    if not args.no_series:
        series=breakpoint_grid(start,stop,knots,60);te=data.emission(series);a=data.evaluate(series);b=data.evaluate(te)
        path=args.output_file.with_name(args.output_file.stem+'_series.tsv');path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('w',newline='') as f:
